#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    char line[128];
    char *end = NULL;
    long value;

    if (fgets(line, sizeof line, stdin) == NULL) {
        fputs("No input available\n", stderr);
        return 1;
    }
    errno = 0;
    value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        fputs("Invalid integer\n", stderr);
        return 1;
    }
    while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r') {
        ++end;
    }
    if (*end != '\0') {
        fputs("Unexpected trailing characters\n", stderr);
        return 1;
    }
    printf("Accepted: %ld\n", value);
    return 0;
}

#include <stdbool.h>
#include <stddef.h>

bool average(const int values[], size_t count, double *result)
{
    long long sum = 0;
    if (result == NULL || (count > 0U && values == NULL) || count == 0U) {
        return false;
    }
    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
    }
    *result = (double)sum / (double)count;
    return true;
}
